"""Private local Spleeter inference adapter. Audio paths are generated by the Rust host.

No uploads or model downloads occur here. Setup installs the isolated runtime and
verifies the upstream checkpoint before this worker is launched.
"""
import json
import math
import os
from pathlib import Path
import sys
import time

KINDS = ("vocals", "drums", "bass", "other")
MODEL_RATE = 44100
SEGMENT_SECONDS = 12
OVERLAP_SECONDS = 2


def event(kind, **values):
    print(json.dumps({"event": kind, **values}), flush=True)


def run(request):
    started = time.perf_counter()
    frames, rate, channels = request["frames"], request["sample_rate"], request["channels"]
    if channels not in (1, 2) or not 8000 <= rate <= 384000:
        raise ValueError("Unsupported separation layout")
    if not isinstance(frames, int) or not 1 <= frames <= 536870912 // (4 * channels):
        raise ValueError("Input exceeds the 512 MiB decoded separation limit")
    source = Path(request["input_pcm"])
    output = Path(request["output_directory"])
    model = Path(request["model_directory"])
    # Python's filesystem accepts Win32 verbatim paths, but TensorFlow 2.12's
    # checkpoint globbing does not. Normalize only this trusted model location.
    model_text = str(model)
    if os.name == "nt" and model_text.startswith("\\\\?\\"):
        model = Path("\\\\" + model_text[8:] if model_text.startswith("\\\\?\\UNC\\") else model_text[4:])
    if source.stat().st_size != frames * channels * 4:
        raise ValueError("Incomplete input PCM")
    if not (model / ".probe").is_file():
        raise ValueError("Install the local stem engine before separating audio")
    output.mkdir(exist_ok=False)
    os.environ.update(MODEL_PATH=str(model.parent), TF_CPP_MIN_LOG_LEVEL="2",
                      TF_NUM_INTEROP_THREADS="1", TF_NUM_INTRAOP_THREADS="4",
                      CUDA_VISIBLE_DEVICES="-1")
    event("progress", fraction=0.03, message="Loading the local separation model")
    import numpy as np
    from scipy.signal import resample_poly
    import tensorflow as tf
    from spleeter.model import EstimatorSpecBuilder
    from spleeter.utils.configuration import load_configuration

    tf.get_logger().setLevel("ERROR")
    tf.compat.v1.disable_eager_execution()
    params = load_configuration("spleeter:4stems-16kHz")
    params["MWF"] = False
    graph = tf.Graph()
    with graph.as_default():
        waveform = tf.compat.v1.placeholder(tf.float32, shape=(None, 2), name="waveform")
        predictions = EstimatorSpecBuilder({"waveform": waveform}, params).outputs
        saver = tf.compat.v1.train.Saver()
    checkpoint = tf.train.latest_checkpoint(str(model))
    if checkpoint is None:
        raise ValueError("The local model checkpoint is missing or incomplete")
    config = tf.compat.v1.ConfigProto(intra_op_parallelism_threads=4, inter_op_parallelism_threads=1,
                                     device_count={"GPU": 0})
    source_audio = np.memmap(source, dtype="<f4", mode="r", shape=(frames, channels))
    outputs = {name: np.memmap(output / f"{name}.f32", dtype="<f4", mode="w+", shape=(frames, channels))
               for name in KINDS}
    weights = np.memmap(output / "overlap.f32", dtype="<f4", mode="w+", shape=(frames,))
    segment = SEGMENT_SECONDS * rate
    overlap = OVERLAP_SECONDS * rate
    stride = segment - overlap
    divisor = math.gcd(rate, MODEL_RATE)
    count = max(1, math.ceil(max(0, frames - segment) / stride) + 1)
    with tf.compat.v1.Session(graph=graph, config=config) as session:
        with graph.as_default():
            saver.restore(session, checkpoint)
        event("progress", fraction=0.1, message="Separating vocals, drums, bass and other instruments")
        for index, start in enumerate(range(0, frames, stride)):
            end = min(start + segment, frames)
            audio = np.asarray(source_audio[start:end], dtype=np.float32)
            if not np.isfinite(audio).all():
                raise ValueError("Input contains non-finite samples")
            if channels == 1:
                audio = np.repeat(audio, 2, axis=1)
            if rate != MODEL_RATE:
                audio = resample_poly(audio, MODEL_RATE // divisor, rate // divisor, axis=0)
            audio = np.ascontiguousarray(audio, dtype=np.float32)
            predicted = session.run(predictions, {waveform: audio})
            window = np.ones(end - start, dtype=np.float32)
            fade = min(overlap, len(window))
            ramp = np.sin(np.linspace(0, np.pi / 2, fade, dtype=np.float32)) ** 2
            if start > 0:
                window[:fade] *= ramp
            if end < frames:
                window[-fade:] *= ramp[::-1]
            for name in KINDS:
                stem = predicted[name]
                if rate != MODEL_RATE:
                    stem = resample_poly(stem, rate // divisor, MODEL_RATE // divisor, axis=0)
                if channels == 1:
                    stem = np.mean(stem, axis=1, keepdims=True)
                if len(stem) < end - start or not np.isfinite(stem).all():
                    raise ValueError(f"The model returned invalid {name} audio")
                outputs[name][start:end] += np.asarray(stem[:end-start], dtype=np.float32) * window[:, None]
                outputs[name].flush()
            weights[start:end] += window
            weights.flush()
            event("progress", fraction=min(0.9, 0.1 + 0.8 * (index + 1) / count),
                  message=f"Separated segment {index + 1} of {count}")
            if end == frames:
                break
    # Normalization is chunked, avoiding an additional full-song allocation.
    for start in range(0, frames, rate * 8):
        end = min(start + rate * 8, frames)
        weight = np.asarray(weights[start:end])
        if not np.all(weight > 0):
            raise ValueError("Separation left an uncovered time region")
        for name in KINDS:
            outputs[name][start:end] /= weight[:, None]
            if not np.isfinite(outputs[name][start:end]).all():
                raise ValueError("Separation produced non-finite audio")
    for stem in outputs.values():
        stem.flush()
    outputs.clear()
    del weight, weights, source_audio
    (output / "overlap.f32").unlink()
    result = {"model": "spleeter-4stems-16khz", "model_release": "v1.4.0",
              "sample_rate": rate, "channels": channels, "frames": frames,
              "stems": list(KINDS), "elapsed_seconds": time.perf_counter() - started,
              "segment_seconds": SEGMENT_SECONDS, "overlap_seconds": OVERLAP_SECONDS}
    (output / "result.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
    event("result", **result)


if __name__ == "__main__":
    try:
        if len(sys.argv) != 2:
            raise ValueError("Expected a private request file")
        request_path = Path(sys.argv[1])
        if request_path.stat().st_size > 16384:
            raise ValueError("Worker request is too large")
        run(json.loads(request_path.read_text(encoding="utf-8")))
    except Exception as error:
        event("error", message=str(error))
        print(f"Local separation failed: {error}", file=sys.stderr)
        raise SystemExit(1)
